#[component]
pub fn Inventory() -> impl IntoView {
    let tab = RwSignal::new("stock");
    view! { <div class="page"><PageHead title=t("Inventory & Warehouse") subtitle="What you hold, where it is and what it cost. Every movement is recorded and valued.">
        {move || crate::state::can("finance.write").then(|| view! { <a class="btn" href="/stock-opening/new">"Opening stock"</a> })}</PageHead>
        <Tabs tabs=vec![("stock", t("Stock")), ("moves", t("Stock Ledger")), ("tr", t("Transfers")), ("adj", t("Adjustments")), ("prod", t("Products")), ("cat", t("Categories")), ("unit", t("Units")), ("wh", t("Warehouses"))] active=tab/>
        {move || match tab.get() { "stock" => view! { <ListPage cfg=&STOCK headless=true/> }.into_any(), "moves" => view! { <ListPage cfg=&MOVES headless=true/> }.into_any(), "tr" => view! { <ListPage cfg=&TRANSFERS headless=true/> }.into_any(), "adj" => view! { <ListPage cfg=&ADJUSTMENTS headless=true/> }.into_any(),
            "prod" => view! { <ListPage cfg=&PRODUCTS headless=true/> }.into_any(), "cat" => view! { <ListPage cfg=&CATEGORIES headless=true/> }.into_any(), "unit" => view! { <ListPage cfg=&UNITS headless=true/> }.into_any(), _ => view! { <ListPage cfg=&WAREHOUSES headless=true/> }.into_any() }}</div> }
}

